import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";

test.describe("All layout", () => {
  test.use({
    inspectorOptions: {
      inspectMode: true,
      viewport: { width: 1600, height: 900 },
    },
  });

  test("All view option is visible and layout shows chat, canvas, and side panel", async ({
    inspectorPage,
  }) => {
    await test.step("Assert All view option is visible in view menu", async () => {
      await ui.viewMenu.actions(inspectorPage).open();
      await ui.viewMenu.assertions(inspectorPage).allOptionIsVisible();
    });

    await flows.allView.openAllLayoutAndAssertPanels(inspectorPage);
  });

  test("Event details open in side panel without hiding canvas, then close restores history", async ({
    inspectorPage,
  }) => {
    await flows.allView.openEventDetailsInAllLayoutAndAssert(inspectorPage);
    await flows.allView.closeEventDetailsAndAssertSidePanelRestored(inspectorPage);
  });

  test("All option is hidden below 1536px breakpoint", async ({ inspectorPage }) => {
    await test.step("Resize below 1536px breakpoint", async () => {
      await inspectorPage.setViewportSize({ width: 1240, height: 768 });
    });

    await test.step("Assert All option is hidden", async () => {
      await ui.viewMenu.actions(inspectorPage).open();
      await ui.viewMenu.assertions(inspectorPage).allOptionIsHidden();
    });
  });
});
